/**
 * Seeds panchangam rows from a pre-computed JSON file into the Google Sheet.
 *
 * Source file: research/panchangam-computed.json
 *   Generated by: python3 scripts/compute-panchangam.py <start> <days>
 *   Computation: PyEphem + Lahiri ayanamsha for New Delhi, IST. Includes
 *   rahu/gulika/yamaganda kalam and day/night choghadiya (single-location,
 *   New Delhi only — no per-city support).
 *
 * Usage:
 *   node scripts/seed-panchangam.mjs                    (dry run)
 *   node scripts/seed-panchangam.mjs --write            (apply)
 *   node scripts/seed-panchangam.mjs --write --replace  (clear existing + write)
 *
 * Safety:
 *   Default: refuses to write dates that already exist in the sheet.
 *   --replace: removes ALL existing panchangam rows then re-inserts
 *              (use this to refresh stale data).
 */

import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';
import { readFileSync } from 'fs';
import { getSheetsClient, SPREADSHEET_ID, parseWriteFlag, colLetter } from './lib-sheets.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));

const WRITE   = parseWriteFlag(process.argv);
const REPLACE = process.argv.includes('--replace');

const sourcePath = resolve(__dirname, '../research/panchangam-computed.json');
const rows = JSON.parse(readFileSync(sourcePath, 'utf8'));

// ─── Sheet connection ─────────────────────────────────────────────────────────

const sheets = await getSheetsClient();
const SHEET_ID = SPREADSHEET_ID;

const HEADERS = [
  'date','tithi_en','tithi_number','paksha',
  'nakshatra_en','yoga_en','karana_en','lunar_month_en',
  'sunrise','sunset','rahu_kalam','gulika_kalam','yamaganda_kalam',
  'choghadiya_day','choghadiya_night',
  'special_event_en','special_event_te','special_event_ta','special_event_hi',
];

// Returns true if row 1 already matches HEADERS exactly. Checking the full
// row (not just that A1 === 'date') matters because adding a new column to
// HEADERS without a matching change here would otherwise leave a stale
// header row silently out of sync with the data columns actually written.
async function hasHeaderRow() {
  const res = await sheets.spreadsheets.values.get({
    spreadsheetId: SHEET_ID,
    range: `panchangam!A1:${colLetter(HEADERS.length - 1)}1`,
  });
  const row = res.data.values?.[0] ?? [];
  return row.length === HEADERS.length && HEADERS.every((h, i) => row[i] === h);
}

// Read existing panchangam dates from the sheet (column A after header)
async function getExistingDates() {
  const res = await sheets.spreadsheets.values.get({
    spreadsheetId: SHEET_ID,
    range: 'panchangam!A:A',
  });
  const values = res.data.values || [];
  // If the first cell is the header, skip it; otherwise the sheet has no header yet
  const dataRows = values[0]?.[0] === 'date' ? values.slice(1) : values;
  return new Set(dataRows.map(r => r[0]).filter(Boolean));
}

// Write header row to A1 (only called when the sheet is empty or missing headers)
async function writeHeaderRow() {
  await sheets.spreadsheets.values.update({
    spreadsheetId: SHEET_ID,
    range: 'panchangam!A1',
    valueInputOption: 'RAW',
    requestBody: { values: [HEADERS] },
  });
  console.log('✓ Wrote header row.');
}

// Get the sheet's internal sheetId for panchangam tab (needed for clear)
async function getPanchangamSheetId() {
  const meta = await sheets.spreadsheets.get({ spreadsheetId: SHEET_ID });
  const sheet = meta.data.sheets.find(s => s.properties.title === 'panchangam');
  return sheet?.properties?.sheetId ?? null;
}

// ─── Dry-run report ───────────────────────────────────────────────────────────

console.log('\n══ seed-panchangam.mjs ═══════════════════════════════════════');
console.log(`Mode:   ${WRITE ? (REPLACE ? '⚡ WRITE + REPLACE' : '⚡ WRITE') : '🔍 DRY RUN'}`);
console.log(`Source: research/panchangam-computed.json (${rows.length} days)`);
console.log(`Range:  ${rows[0]?.date} → ${rows[rows.length - 1]?.date}`);
console.log(`City:   New Delhi, India (IST, Lahiri ayanamsha)`);

const existingDates = await getExistingDates();
const newRows    = rows.filter(r => !existingDates.has(r.date));
const skipRows   = rows.filter(r =>  existingDates.has(r.date));

console.log(`\nExisting rows in sheet: ${existingDates.size}`);
console.log(`New rows to append:     ${newRows.length}`);
console.log(`Already present:        ${skipRows.length}`);

if (skipRows.length > 0 && !REPLACE) {
  console.log(`\nSkipped dates (already exist):`);
  skipRows.slice(0, 5).forEach(r => console.log(`  ${r.date}`));
  if (skipRows.length > 5) console.log(`  … and ${skipRows.length - 5} more`);
}

// Sample output
console.log('\nSample rows:');
const samples = [rows[0], rows[Math.floor(rows.length / 2)], rows[rows.length - 1]];
samples.forEach(r => {
  console.log(`  ${r.date}  ${r.paksha} ${r.tithi_en}  ${r.nakshatra_en}  ${r.lunar_month_en}  ${r.sunrise}–${r.sunset}`);
});

if (!WRITE) {
  console.log('\nDry run — no changes written. Re-run with --write to apply.');
  process.exit(0);
}

// ─── Write ────────────────────────────────────────────────────────────────────

const headerExists = await hasHeaderRow();
if (!headerExists) await writeHeaderRow();

if (REPLACE) {
  // Delete all data rows (keep header row 1)
  const sheetId = await getPanchangamSheetId();
  if (sheetId === null) {
    console.error('Could not find panchangam tab sheetId — aborting.');
    process.exit(1);
  }
  // Only delete if there are existing rows
  if (existingDates.size > 0) {
    await sheets.spreadsheets.batchUpdate({
      spreadsheetId: SHEET_ID,
      requestBody: {
        requests: [{
          deleteDimension: {
            range: {
              sheetId,
              dimension: 'ROWS',
              startIndex: 1,   // row index 1 = second row (0-indexed), i.e. first data row
              endIndex: existingDates.size + 1,
            },
          },
        }],
      },
    });
    console.log(`\n✓ Cleared ${existingDates.size} existing rows.`);
  }
  // Now write all rows
  const toWrite = rows;
  const appendValues = toWrite.map(r => [
    r.date, r.tithi_en, r.tithi_number, r.paksha,
    r.nakshatra_en, r.yoga_en, r.karana_en, r.lunar_month_en,
    r.sunrise, r.sunset, r.rahu_kalam, r.gulika_kalam, r.yamaganda_kalam,
    r.choghadiya_day, r.choghadiya_night,
    r.special_event_en, r.special_event_te, r.special_event_ta, r.special_event_hi,
  ]);
  await sheets.spreadsheets.values.append({
    spreadsheetId: SHEET_ID,
    range: 'panchangam!A1',
    valueInputOption: 'RAW',
    requestBody: { values: appendValues },
  });
  console.log(`✓ Inserted ${appendValues.length} rows.`);
} else {
  // Append-only: only new dates
  if (newRows.length === 0) {
    console.log('\nAll dates already present — nothing to append.');
    process.exit(0);
  }
  const appendValues = newRows.map(r => [
    r.date, r.tithi_en, r.tithi_number, r.paksha,
    r.nakshatra_en, r.yoga_en, r.karana_en, r.lunar_month_en,
    r.sunrise, r.sunset, r.rahu_kalam, r.gulika_kalam, r.yamaganda_kalam,
    r.choghadiya_day, r.choghadiya_night,
    r.special_event_en, r.special_event_te, r.special_event_ta, r.special_event_hi,
  ]);
  await sheets.spreadsheets.values.append({
    spreadsheetId: SHEET_ID,
    range: 'panchangam!A1',
    valueInputOption: 'RAW',
    requestBody: { values: appendValues },
  });
  console.log(`\n✓ Appended ${appendValues.length} new panchangam rows.`);
}

console.log('\nDone. Trigger a deploy (push to GitHub) to publish the new data.');
